import { ReactNode } from 'react';

import { ConvertibleUnit, FormatOptions, Unit } from '@dynatrace-sdk/units';

import { MultiMeterBarChartInternalTooltipConfig } from './multi-meter-bar-chart-internal.js';
import { MultiMeterBarSegmentProps } from './multi-meter-bar-chart.js';
import {
  CustomColorPalette,
  ColorPalette,
} from '../../../core/types/color-palette.js';
import { Formatter } from '../../../core/types/formatter.js';
import {
  SlotWithAutoDefault,
  MeterBarSize,
} from '../../shared/types/meter-bars.js';

export interface MultiMeterBarChartSlots {
  icon?: ReactNode;
  label?: ReactNode;
  min?: SlotWithAutoDefault;
  max?: SlotWithAutoDefault;
  value?: SlotWithAutoDefault;
  segments: MultiMeterBarSegmentProps[];
  legend?: boolean;
  tooltip?: MultiMeterBarChartInternalTooltipConfig;
}

/**
 * Configuration props to be provided by the consumer
 */
export interface MultiMeterBarChartConsumerConfig {
  /**
   * The color palette
   * @defaultValue 'categorical'
   */
  colorPalette?: ColorPalette | CustomColorPalette;
  /**
   * The size to apply to meter bar charts that are within the configuration
   * @defaultvalue 'size16'
   */
  size?: MeterBarSize;
  /**
   * Min value for the meter bar chart scale
   * @defaultValue 0
   */
  min?: number;
  /**
   * Max value for the meter bar chart scale
   * @defaultValue 100
   */
  max?: number;
  /**
   * Custom Formatter for the chart
   */
  formatter?: Formatter | FormatOptions<Unit, ConvertibleUnit>;
  /**
   * Tooltip configuration
   */
  tooltip?: MultiMeterBarChartTooltipConsumerConfig;
  /**
   * Set to true to display the legend and false to hide it.
   * @defaultValue false
   */
  legend?: boolean;
}

/**
 * Tooltip configuration to be provided by the consumer
 */
export interface MultiMeterBarChartTooltipConsumerConfig {
  /**
   * Defines how the tooltip should display the chart information
   * @defaultValue 'single'
   */
  variant?: MultiMeterBarChartTooltipVariant;
  /**
   * Set to true to display the tooltip and false to hide it
   * @defaultValue false
   */
  enabled?: boolean;
}

// TODO this should be already a shared type in core
export const multiMeterBarChartTooltipVariantOptions = [
  'single',
  'shared',
] as const;

/**
 * The different variants available to use in the tooltip subcomponent
 */
export type MultiMeterBarChartTooltipVariant =
  (typeof multiMeterBarChartTooltipVariantOptions)[number];
